WITH src AS (SELECT * FROM shipments WHERE carrier = 'Kerry' OR order_id = 32), ShipmentsStats AS (SELECT CASE WHEN cost >= 85 THEN 'high' WHEN cost >= 43 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(CASE WHEN status = 'DELIVERED' THEN 1 ELSE 0 END) AS delivered_count FROM src GROUP BY CASE WHEN cost >= 85 THEN 'high' WHEN cost >= 43 THEN 'mid' ELSE 'low' END) SELECT cost_bucket, delivered_count FROM ShipmentsStats WHERE delivered_count > 47
